        access_token=venmo_access_token,
        user_email=ME,
        min_created_at=month_start_str,
        max_created_at=now_str,
        page_index=page_index,
        page_limit=PAGE_LIMIT
    )
    if not tx_page or not isinstance(tx_page, list) or len(tx_page) == 0:
        break

    for tx in tx_page:
        if not isinstance(tx, dict):
            continue
        for side_key in ["from", "to", "sender", "recipient", "payee", "payer", "other_user", "counterparty"]:
            if isinstance(tx.get(side_key), dict):
                em = tx[side_key].get("email")
                if em and em != ME:
                    counterparty_emails.add(em)
        for em_key in ["from_email", "to_email", "counterparty_email", "other_user_email"]:
            em = tx.get(em_key)
            if em and em != ME:
                counterparty_emails.add(em)

    page_index += 1

# 2) Current friends
current_friend_emails = set()
page_index = 0
while True:
    friends_page = apis.venmo.search_friends(
        access_token=venmo_access_token,
        user_email=ME,
        query="",
        page_index=page_index,
        page_limit=PAGE_LIMIT
    )
    if not friends_page or not isinstance(friends_page, list) or len(friends_page) == 0:
        break

    for u in friends_page:
        if isinstance(u, dict):
            em = u.get("email")
            if em:
                current_friend_emails.add(em)

    page_index += 1

to_befriend = counterparty_emails - current_friend_emails
to_unfriend = current_friend_emails - counterparty_emails

for em in sorted(to_befriend):
    apis.venmo.add_friend(access_token=venmo_access_token, user_email=em)

for em in sorted(to_unfriend):
    apis.venmo.remove_friend(access_token=venmo_access_token, user_email=em)

apis.supervisor.complete_task()
print({"befriended_count": len(to_befriend), "unfriended_count": len(to_unfriend)})", "step": 12})
